import io
import re

p = "build_report.py"
s = io.open(p, encoding="utf-8").read()


def rep(a, b, count=1):
    global s
    assert s.count(a) == count, (s.count(a), a[:80])
    s = s.replace(a, b)


# ── 1. imports + chạy code ─────────────────────────────────────────────
rep("import html\nimport os\n", "import base64\nimport glob\nimport html\nimport os\nimport shutil\nimport subprocess\nimport sys\n")
rep('OUT = os.path.join(HERE, "bao_cao_xu_ly_du_lieu.html")\n', '''OUT = os.path.join(HERE, "bao_cao_xu_ly_du_lieu.html")
CODE = os.path.join(HERE, "report_code")
RSCRIPT = shutil.which("Rscript") or next(iter(sorted(glob.glob(r"C:/Program Files/R/R-*/bin/Rscript.exe"))), None)


def run_snippet(lang, sid):
    """Chạy report_code/<lang>/<sid>.<ext> trong thư mục dự án, trả về (mã nguồn, stdout, danh sách hình)."""
    ext = "py" if lang == "py" else "R"
    path = os.path.join(CODE, lang, f"{sid}.{ext}")
    src = open(path, encoding="utf-8").read()
    for f in glob.glob(os.path.join(CODE, "fig", f"{lang}_{sid}_*.png")):
        os.remove(f)
    if lang == "py":
        cmd = [sys.executable, path]
    elif RSCRIPT:
        cmd = [RSCRIPT, path]
    else:
        return src, "(Máy dựng báo cáo không có R — chưa chạy được đoạn code này.)", []
    env = dict(os.environ, PYTHONIOENCODING="utf-8")
    r = subprocess.run(cmd, cwd=HERE, capture_output=True, env=env)
    out = r.stdout.decode("utf-8", "replace").rstrip()
    if r.returncode != 0:
        raise RuntimeError(f"{path} lỗi:\\n{r.stderr.decode('utf-8', 'replace')}")
    figs = sorted(glob.glob(os.path.join(CODE, "fig", f"{lang}_{sid}_*.png")))
    return src, out, figs


def code_block(sid, num):
    panes, tabs = [], []
    for i, (lang, name, ext) in enumerate([("py", "Python", "py"), ("r", "R", "R")]):
        src, out, figs = run_snippet(lang, sid)
        imgs = "".join(
            f'<img src="data:image/png;base64,{base64.b64encode(open(f, "rb").read()).decode()}" '
            f'alt="Hình do code {name} tạo ra ({os.path.basename(f)})" loading="lazy">' for f in figs)
        hid = "" if i == 0 else " hidden"
        on = " on" if i == 0 else ""
        tabs.append(f'<button type="button" class="tab{on}" data-lang="{lang}">{name}</button>')
        panes.append(
            f'<div class="pane" data-lang="{lang}"{hid}>'
            f'<div class="fname">report_code/{lang}/{sid}.{ext}</div>'
            f'<pre class="src">{html.escape(src.rstrip())}</pre>'
            f'<div class="outhead">Kết quả chạy</div>'
            f'<pre class="out">{html.escape(out) if out else "(không in ra màn hình)"}</pre>'
            f'{f"<div class=imgs>{imgs}</div>" if imgs else ""}</div>')
    print(f"  đã chạy code mục {sid} (Python + R)")
    return (f'<h3>{num}. Code và kết quả chạy</h3>'
            f'<div class="codebox"><div class="tabs">{"".join(tabs)}'
            f'<button type="button" class="copy">Sao chép code</button></div>{"".join(panes)}</div>')
''')

# ── 2. bỏ bảng nguồn dữ liệu ───────────────────────────────────────────
rep("{sources_html}\n", "")

# ── 3. từ điển: biến mới ───────────────────────────────────────────────
rep('    ("year, quarter, period", "year, quarter", "Năm, quý báo cáo; period dạng 2026Q3", "Thời gian", "–"),\n',
    '    ("year, quarter", "year, quarter", "Năm, quý báo cáo", "Thời gian", "–"),\n'
    '    ("period, period_end", "–", "Kỳ báo cáo dạng 2026Q3 và ngày cuối kỳ", "Biến mới", "–"),\n')
rep('''def dict_table(rows):
    return table(["Tên trong CSV", "Tên gốc", "Ý nghĩa", "Loại", "Đơn vị"],
                 [[code(a) if a != "–" and not a.startswith("&") else (f"<code>{a}</code>" if a.startswith("&") else a),
                   code(b) if b != "–" else "–", c, d, u] for a, b, c, d, u in rows], cls="dict")''',
'''NEW_VARS = {"period, period_end", "flow_basis_*_applied", "chk_*", "missing_critical", "year_month, quarter",
            "US_CPI_YoY", "US_CPI_imputed", "FED_target_upper_eoq / _avg", "DGS10_quarterly_avg",
            "VN_CPI_data_type", "rate_before, rate_after", "change_pp", "&lt;rate_code&gt;_eop / _avg",
            "uncertain_level_codes"}
NEW_HNX = {"ticker", "is_subsidiary", "issue_channel", "sector_group", "is_irregular_report",
           "mapping_confidence", "bond_default_flag"}


def dict_table(rows, new=NEW_VARS):
    out = []
    for a, b, c, d, u in rows:
        name = f"<code>{a}</code>" if a.startswith("&") else code(a)
        out.append([name, code(b) if b != "–" else "–", c, "Biến mới" if a in new else d, u])
    return table(["Tên trong CSV", "Tên gốc", "Ý nghĩa", "Loại", "Đơn vị"], out, cls="dict")


dict_feat = [
    ("ebit_true", "–", "LNTT + chi phí lãi vay (EBIT đúng nghĩa)", "Biến mới", "VND"),
    ("total_debt", "–", "Vay ngắn hạn + vay dài hạn", "Biến mới", "VND"),
    ("net_debt", "–", "Tổng nợ vay − tiền − đầu tư ngắn hạn", "Biến mới", "VND"),
    ("adv_customers_total", "–", "Người mua trả tiền trước ngắn hạn + dài hạn", "Biến mới", "VND"),
    ("interest_capitalised_gap", "–", "Lãi vay đã trả − chi phí lãi vay ghi nhận", "Biến mới", "VND"),
    ("liquid_to_st_debt", "–", "(Tiền + đầu tư ngắn hạn) / vay ngắn hạn", "Biến mới", "lần"),
    ("debt_to_equity", "–", "Tổng nợ vay / vốn chủ sở hữu", "Biến mới", "lần"),
    ("icr_ebit", "–", "EBIT / chi phí lãi vay", "Biến mới", "lần"),
    ("cfo_to_interest_paid", "–", "CFO / lãi vay đã trả", "Biến mới", "lần"),
    ("adv_to_liabilities", "–", "Người mua trả trước / nợ phải trả", "Biến mới", "tỷ lệ"),
    ("DGS10_mom_chg", "–", "Thay đổi lợi suất 10 năm so với tháng trước", "Biến mới", "điểm %"),
    ("FED_mom_chg", "–", "Thay đổi trần lãi suất Fed so với tháng trước", "Biến mới", "điểm %"),
    ("US_real_10y", "–", "Lợi suất 10 năm − lạm phát Mỹ YoY", "Biến mới", "%/năm"),
    ("US_term_spread", "–", "Lợi suất 10 năm − trần lãi suất Fed (trung bình quý)", "Biến mới", "điểm %"),
    ("*_outlier", "–", "Cờ ngoại lai theo 1,5×IQR", "Biến mới", "–"),
]''')
rep('"<h3>0.4. Sự kiện trái phiếu (HNX) — <code>clean_hnx_*.csv</code></h3>" + dict_table(dict_hnx) +\n'
    '    "<p>Các biến tạo thêm (tỷ số tài chính, lãi suất thực…) được mô tả riêng ở <a href=\'#s4\'>mục 4</a>.</p>"',
    '"<h3>0.4. Sự kiện trái phiếu (HNX) — <code>clean_hnx_*.csv</code></h3>" + dict_table(dict_hnx, NEW_HNX) +\n'
    '    "<h3>0.5. Biến tạo thêm ở bước feature engineering</h3>" + dict_table(dict_feat) +\n'
    '    "<p>Cột “Loại” ghi <b>Biến mới</b> cho mọi biến do nhóm tự tạo, không có sẵn trong file gốc. "\n'
    '    "Cách tính chi tiết ở <a href=\'#s4\'>mục 4</a>.</p>"')
rep('"Bảng dưới liệt kê các biến có trong bộ dữ liệu sau khi làm sạch. Cột “Tên gốc” là tên trường trong file thô; "',
    '"Bảng dưới liệt kê các biến có trong bộ dữ liệu sau khi làm sạch. Cột “Tên gốc” là tên trường trong file thô "\n'
    '    "(ghi “–” nếu là biến mới); "')

# ── 4. gắn code vào từng mục ───────────────────────────────────────────
nums = {"s0": "0.6", "s1": "1.3", "s2": "2.7", "s3": "3.4", "s4": "4.3", "s5": "5.6", "s6": "6.2", "s7": "7.4"}
for sid, num in nums.items():
    pat = re.compile(rf'sec\("{sid}", ("[^"]+"), (body{sid[1]})\)')
    assert len(pat.findall(s)) == 1, sid
    s = pat.sub(lambda m: f'sec("{sid}", {m.group(1)}, {m.group(2)} + code_block("{sid}", "{num}"))', s)
rep("body6 = chart_nulls() + chart_coverage() + chart_hnx()",
    'body6 = ("<h3>6.1. Biểu đồ (rê chuột để xem số liệu)</h3>" + chart_nulls() + chart_coverage() + chart_hnx())')

# ── 5. CSS + JS ────────────────────────────────────────────────────────
rep("@media (max-width:900px)", """.codebox{border:1px solid var(--line);border-radius:6px;margin:0 0 26px;overflow:hidden}
.tabs{display:flex;align-items:stretch;border-bottom:1px solid var(--line);background:var(--th)}
.tab,.copy{font:inherit;font-size:14px;border:0;background:none;color:var(--ink2);cursor:pointer;padding:8px 18px}
.tab{border-bottom:2px solid transparent;margin-bottom:-1px}
.tab:hover,.copy:hover{color:var(--ink)}
.tab.on{color:var(--ink);font-weight:600;border-bottom-color:var(--ink);background:var(--bg)}
.copy{margin-left:auto;font-size:13px}
.fname{font:12.5px Consolas,Menlo,monospace;color:var(--muted);padding:8px 16px 0}
.pane pre{margin:0;border-radius:0;background:var(--bg);max-height:460px}
.pane pre.src{padding-top:8px}
.outhead{font-size:13px;font-weight:600;color:var(--ink2);padding:7px 16px;background:var(--th);
border-top:1px solid var(--line);border-bottom:1px solid var(--line)}
.pane pre.out{background:var(--code)}
.imgs{padding:12px 16px;display:grid;gap:12px;border-top:1px solid var(--line)}
.imgs img{max-width:100%;height:auto;border:1px solid var(--line);background:#fff}
@media (max-width:900px)""")
rep("document.querySelectorAll('main section').forEach(s=>io.observe(s));", """document.querySelectorAll('main section').forEach(s=>io.observe(s));
function setLang(l){document.querySelectorAll('.codebox').forEach(b=>{
 b.querySelectorAll('.tab').forEach(t=>t.classList.toggle('on',t.dataset.lang===l));
 b.querySelectorAll('.pane').forEach(p=>p.hidden=p.dataset.lang!==l)});
 try{localStorage.setItem('codeLang',l)}catch(e){}}
document.addEventListener('click',ev=>{const t=ev.target.closest('.tab');if(t){setLang(t.dataset.lang);return}
 const c=ev.target.closest('.copy');if(c){const pane=c.closest('.codebox').querySelector('.pane:not([hidden]) .src');
 const done=()=>{c.textContent='Đã sao chép';setTimeout(()=>c.textContent='Sao chép code',1500)};
 if(navigator.clipboard){navigator.clipboard.writeText(pane.textContent).then(done,()=>{})}}});
try{const l=localStorage.getItem('codeLang');if(l)setLang(l)}catch(e){}""")

io.open(p, "w", encoding="utf-8", newline="\n").write(s)
print("patched")

