        r'|(?P<num>\b\d+(?:\.\d+)?(?:[eE][+-]?\d+)?L?\b)|(?P<id>[A-Za-z.][A-Za-z0-9._]*)'
        r'|(?P<ws>\s+)|(?P<op>%[^%\n]*%|<-|.)'),
}


def imported_modules(src):
    """Tên module/alias sau `import` (vd. pd, np, glob) — Pylance tô màu xanh ngọc."""
    names = set()
