# kể cả tô màu ngoặc theo tầng (bracket pair colorization).
PY_CONTROL = {"import", "from", "as", "for", "in", "if", "elif", "else", "return", "while", "break",
              "continue", "with", "try", "except", "finally", "raise", "pass", "yield", "assert", "del"}
