PY_TYPES = {"int", "str", "float", "list", "dict", "set", "tuple", "bool", "object"}
R_CONTROL = {"if", "else", "for", "in", "while", "repeat", "return", "next", "break"}
R_STORAGE = {"function", "TRUE", "FALSE", "NULL", "NA", "Inf", "NaN", "NA_real_", "NA_character_"}
BRACKETS = ["#FFD700", "#DA70D6", "#179FFF"]

TOKEN_PY = re.compile(r'(?P<com>#[^\n]*)|(?P<str>[rRfFbB]{0,2}("""[\s\S]*?"""|\'\'\'[\s\S]*?\'\'\'|"(?:\\.|[^"\\\n])*"|\'(?:\\.|[^\'\\\n])*\'))'
                      r'|(?P<num>\b\d+(?:\.\d+)?(?:[eE][+-]?\d+)?\b)|(?P<id>[A-Za-z_]\w*)|(?P<ws>\s+)|(?P<op>.)')
TOKEN_R = re.compile(r'(?P<com>#[^\n]*)|(?P<str>"(?:\\.|[^"\\])*"|\'(?:\\.|[^\'\\])*\')|(?P<bt>`[^`]*`)'
                     r'|(?P<num>\b\d+(?:\.\d+)?(?:[eE][+-]?\d+)?L?\b)|(?P<id>[A-Za-z.][A-Za-z0-9._]*)|(?P<ws>\s+)|(?P<op>%[^%\n]*%|<-|.)')


def _span(text, color):
    return f'<span style="color:{color}">{html.escape(text)}</span>'


def highlight(src, lang):
    rx = TOKEN_PY if lang == "py" else TOKEN_R
    toks = [(m.lastgroup, m.group()) for m in rx.finditer(src)]
    modules = set()
    if lang == "py":                                   # tên module đã import -> màu xanh ngọc như Pylance
        for line in src.splitlines():
            line = line.split("#")[0]
            if re.match(r"\s*(import|from)\s", line):
                part = line.split(" import ")[-1] if line.lstrip().startswith("from") else line.split("import", 1)[1]
                for item in part.split(","):
                    name = item.split(" as ")[-1].strip()
                    if name and not name[0].isupper() and name.islower():
                        modules.add(name)
                if line.lstrip().startswith("from"):
                    modules.discard("")
    out, depth = [], 0
    sig = [i for i, (k, _) in enumerate(toks) if k != "ws"]
    nxt = {a: (toks[b][1] if j + 1 < len(sig) else "") for j, (a, b) in enumerate(zip(sig, sig[1:] + [None])) if b is not None}
    prv = {b: toks[a][1] for a, b in zip(sig, sig[1:])}
    for i, (kind, t) in enumerate(toks):
        after, before = nxt.get(i, ""), prv.get(i, "")
        if kind == "com":
            out.append(_span(t, "#6A9955"))
        elif kind == "str":
            out.append(_span(t, "#CE9178"))
        elif kind == "num":
            out.append(_span(t, "#B5CEA8"))
        elif kind == "bt":
            out.append(_span(t, "#9CDCFE"))
        elif kind == "id":
            control, storage = (PY_CONTROL, PY_STORAGE) if lang == "py" else (R_CONTROL, R_STORAGE)
            if t in control:
                c = "#C586C0"
            elif t in storage:
                c = "#569CD6"
            elif before == "def" or after == "(":
                c = "#4EC9B0" if (t[0].isupper() or t in PY_TYPES) and lang == "py" and before != "def" else "#DCDCAA"
            elif before in (".", "$", "@"):
                c = "#9CDCFE"
            elif t in modules:
                c = "#4EC9B0"
            elif t.isupper() and len(t) > 1 or re.fullmatch(r"[A-Z][A-Z0-9_]+", t):
                c = "#4FC1FF"
            else:
                c = "#9CDCFE"
            out.append(_span(t, c))
        elif kind == "op" and t in "([{":
            out.append(_span(t, BRACKETS[depth % 3]))
            depth += 1
        elif kind == "op" and t in ")]}":
            depth = max(depth - 1, 0)
            out.append(_span(t, BRACKETS[depth % 3]))
        else:
            out.append(html.escape(t))
    return "".join(out)

