<!DOCTYPE html>
<html lang="vi">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Ai sẽ hụt tiền? — Stress test thanh khoản chủ đầu tư nhà ở niêm yết</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link href="https://fonts.googleapis.com/css2?family=Source+Serif+4:opsz,wght@8..60,600;8..60,800&family=Be+Vietnam+Pro:wght@400;500;600&family=JetBrains+Mono:wght@400;600&display=swap" rel="stylesheet">
<style>
:root{--ink:#16232b;--ink2:#46545c;--mute:#7c878c;--paper:#e9ece6;--card:#f4f5f1;--line:#d3d8d0;--dark:#13232a;--teal:#1d6b70;--red:#a8322d;--ochre:#c08a2e;--orange:#d0662f;--green:#3f7f4f;}
*{box-sizing:border-box}
html{scroll-behavior:smooth;scroll-padding-top:70px}
body{margin:0;background:var(--paper);color:var(--ink);font-family:"Be Vietnam Pro",system-ui,sans-serif;font-size:16px;line-height:1.6}
nav{position:sticky;top:0;z-index:20;background:rgba(233,236,230,.94);backdrop-filter:blur(6px);border-bottom:1px solid var(--line)}
nav .in{max-width:1180px;margin:auto;display:flex;gap:26px;align-items:center;padding:14px 24px;overflow-x:auto;white-space:nowrap}
nav b{font-family:"Source Serif 4",Georgia,serif;font-size:19px;letter-spacing:.5px}
nav a{color:var(--ink2);text-decoration:none;font-weight:500;font-size:15px}
nav a:hover{color:var(--red)}
.hero{background:var(--dark);color:#eef1ec;padding:70px 0 60px}
.wrap{max-width:1180px;margin:auto;padding:0 24px}
h1,h2{font-family:"Source Serif 4",Georgia,serif;font-weight:800;letter-spacing:-.5px;line-height:1.08;margin:0}
h1{font-size:clamp(40px,6vw,72px)}
h2{font-size:clamp(30px,4vw,44px)}
.hero p.lead{font-size:20px;max-width:820px;color:#c9d2cf;margin:22px 0 34px}
.hero p.lead b{color:#fff}
.kicker{font-family:"JetBrains Mono",monospace;font-size:12px;letter-spacing:2px;text-transform:uppercase;color:var(--ochre);margin-bottom:14px}
.tiles{display:grid;grid-template-columns:repeat(auto-fill,minmax(118px,1fr));gap:10px;background:#0e1b20;border:1px solid #24363d;padding:18px;border-radius:4px}
.tile{padding:14px 12px;border-radius:3px;color:#fff;cursor:default;transition:transform .15s}
.tile:hover{transform:translateY(-3px)}
.tile .t{font-family:"JetBrains Mono",monospace;font-weight:600;font-size:18px}
.tile .v{font-size:13px;opacity:.9}
.legend{display:flex;gap:18px;flex-wrap:wrap;font-size:13px;margin-top:14px;color:#aab6b2}
.legend i,.lg i{display:inline-block;width:12px;height:12px;border-radius:2px;margin-right:6px;vertical-align:-1px}
section{padding:72px 0 40px;border-bottom:1px solid var(--line)}
.sub{color:var(--ink2);max-width:860px;font-size:17px;margin:16px 0 30px}
.grid2{display:grid;grid-template-columns:1.25fr 1fr;gap:40px;align-items:start}
@media(max-width:900px){.grid2{grid-template-columns:1fr}}
.cap{font-size:15px;color:var(--ink2);font-weight:600;margin-bottom:6px}
.note{font-size:13px;color:var(--mute);margin-top:8px}
.card{background:var(--card);border:1px solid var(--line);border-radius:4px;padding:20px}
svg text{font-family:"Be Vietnam Pro",sans-serif}
.num{font-family:"JetBrains Mono",monospace}
table{border-collapse:collapse;width:100%;font-size:14px}
th{text-align:left;font-weight:600;color:var(--ink2);border-bottom:2px solid var(--ink);padding:8px 6px;font-size:13px}
td{border-bottom:1px solid var(--line);padding:9px 6px}
td.r,th.r{text-align:right}
.badge{display:inline-block;padding:2px 9px;border-radius:20px;color:#fff;font-size:12px;font-weight:600}
#tip{position:fixed;pointer-events:none;background:var(--ink);color:#fff;padding:9px 12px;border-radius:3px;font-size:13px;line-height:1.45;opacity:0;transition:opacity .1s;z-index:50;max-width:300px}
.ctrl{display:grid;grid-template-columns:repeat(3,1fr);gap:18px 30px}
@media(max-width:900px){.ctrl{grid-template-columns:1fr}}
.ctrl label{display:block;font-size:14px;font-weight:600}
.ctrl label span{float:right;font-family:"JetBrains Mono",monospace;color:var(--red)}
.ctrl small{display:block;color:var(--mute);font-size:12px;line-height:1.4}
input[type=range]{width:100%;accent-color:var(--teal)}
.presets button{background:none;border:1px solid var(--ink);padding:6px 14px;margin:0 8px 8px 0;font:inherit;font-size:13px;cursor:pointer;border-radius:2px}
.presets button:hover,.presets button.on{background:var(--ink);color:#fff}
.recs{display:grid;grid-template-columns:repeat(auto-fill,minmax(340px,1fr));gap:16px}
.rec{background:var(--card);border:1px solid var(--line);border-left:5px solid;padding:16px 18px;border-radius:3px}
.rec h4{margin:0 0 4px;font-family:"Source Serif 4",serif;font-size:21px}
.rec .who{font-size:12px;letter-spacing:1px;text-transform:uppercase;color:var(--mute);margin-top:10px;font-weight:600}
.rec ul{margin:4px 0 0;padding-left:18px;font-size:14px}
.sel{font:inherit;padding:5px 8px;border:1px solid var(--ink);background:var(--card)}
.small-mult{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}
.crit{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:14px;margin-bottom:26px}
.crit .card h5{margin:0 0 6px;font-size:15px}.crit .card p{margin:4px 0;font-size:13.5px;color:var(--ink2)}
.crit .card .th{font-family:"JetBrains Mono",monospace;font-size:13px;color:var(--red)}
.gcards{display:grid;grid-template-columns:repeat(auto-fill,minmax(255px,1fr));gap:14px}
.gcard{background:var(--card);border:1px solid var(--line);border-top:6px solid;padding:16px;border-radius:3px;font-size:13.5px}
.gcard h4{margin:0;font-family:"Source Serif 4",serif;font-size:22px}.gcard .mem{font-family:"JetBrains Mono",monospace;font-size:13px;margin:4px 0 8px;color:var(--ink2)}
.gcard dl{margin:0}.gcard dt{font-weight:600;font-size:12px;text-transform:uppercase;letter-spacing:.8px;color:var(--mute);margin-top:8px}.gcard dd{margin:2px 0 0}
.kpis{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:12px;margin-bottom:24px}
.kpi{background:var(--card);border:1px solid var(--line);padding:14px 16px;border-radius:3px}.kpi .v{font-family:"Source Serif 4",serif;font-size:30px;font-weight:800}.kpi .l{font-size:13px;color:var(--ink2)}
.pol{counter-reset:p;list-style:none;padding:0;margin:0}.pol li{counter-increment:p;position:relative;padding:12px 0 12px 44px;border-bottom:1px solid var(--line);font-size:15px}
.pol li:before{content:counter(p);position:absolute;left:0;top:10px;width:30px;height:30px;border-radius:50%;background:var(--ink);color:#fff;text-align:center;line-height:30px;font-weight:600}
