3	const C={ink:'#16232b',mute:'#7c878c',line:'#d3d8d0',teal:'#1d6b70',red:'#a8322d',ochre:'#c08a2e',orange:'#d0662f',green:'#3f7f4f'};
4	const NS='http://www.w3.org/2000/svg';
