18	/* ---------- MODEL ---------- */
19	const P={s:45,dr:3,roll:60,col:30,fire:0,hc:30};
20	const R0=9; // lãi vay bình quân giả định %
21	function model(t,p){
22	 const b=last(t),T=D.firms[t].ttm,s=p.s/100;
23	 const sga=(T.sell||0)+(T.adm||0);
24	 const liquid=b.liquid, recv=b.short_term_receivables*p.col/100*(1-s);
25	 const core=T.gp*(1-s)-sga;
26	 const fire=b.inventory*p.fire/100*(1-p.hc/100);
27	 const debt=b.short_term_liabilities*(1-p.roll/100);
28	 const interest=T.fin*(1+p.dr/R0);
29	 const src=liquid+recv+core+fire, need=debt+interest;
30	 const gap=src-need, cov=src/need;
31	 // gap(s) linear: A - s*B
32	 const B=b.short_term_receivables*p.col/100+T.gp;
33	 const A=liquid+b.short_term_receivables*p.col/100+T.gp-sga+fire-need;
34	 const sMax=A<0?0:Math.min(100,A/B*100);
35	 // rollover needed: src - STL*(1-r) - interest =0
36	 const rNeed=Math.max(0,Math.min(100,(1-(src-interest)/b.short_term_liabilities)*100));
37	 return {t,liquid,recv,core,fire,debt,interest,src,need,gap,cov,sMax,A,rNeed,b,T,sga};
38	}
