44	function burden(m,p){p=p||P;if(m.gap>=0)return{S:0,inv:0,bank:0,rest:0};const S=-m.gap;
45	 const inv=Math.min(S,m.b.inventory*Math.max(0,FIRE_MAX-p.fire)/100*(1-p.hc/100));
46	 const bank=Math.min(S-inv,m.b.short_term_liabilities*Math.max(0,ROLL_MAX-p.roll)/100);
47	 return{S,inv,bank,rest:Math.max(0,S-inv-bank)}}
