const F=['DIG','DXG','HPX','KDH','NLG','NVL','PDR','QCG','VHM'];
const NAME={DIG:'DIC Corp',DXG:'Đất Xanh',HPX:'Hải Phát',KDH:'Khang Điền',NLG:'Nam Long',NVL:'Novaland',PDR:'Phát Đạt',QCG:'Quốc Cường Gia Lai',VHM:'Vinhomes'};
const C={ink:'#16232b',mute:'#7c878c',line:'#d3d8d0',teal:'#1d6b70',red:'#a8322d',ochre:'#c08a2e',orange:'#d0662f',green:'#3f7f4f'};
const NS='http://www.w3.org/2000/svg';
const last=t=>D.firms[t].bs[D.firms[t].bs.length-1];
const fmt=(v,d=0)=>v==null||isNaN(v)?'–':v.toLocaleString('vi-VN',{minimumFractionDigits:d,maximumFractionDigits:d});
const fx=v=>fmt(v,2)+'×';
const tip=document.getElementById('tip');
function showTip(e,h){tip.innerHTML=h;tip.style.opacity=1;let x=e.clientX+14,y=e.clientY+14;if(x+310>innerWidth)x=e.clientX-314;tip.style.left=x+'px';tip.style.top=y+'px'}
function hideTip(){tip.style.opacity=0}
function el(tag,attrs,parent,txt){const n=document.createElementNS(NS,tag);for(const k in attrs)n.setAttribute(k,attrs[k]);if(txt!=null)n.textContent=txt;if(parent)parent.appendChild(n);return n}
function svg(id,w,h){const box=document.getElementById(id);box.innerHTML='';return el('svg',{viewBox:`0 0 ${w} ${h}`,width:'100%',style:'display:block;overflow:visible'},box)}
function hover(n,f){n.addEventListener('mousemove',e=>showTip(e,f()));n.addEventListener('mouseleave',hideTip);n.style.cursor='default'}
function tierCol(c){return c>=1.2?C.green:c>=1?C.ochre:c>=0.7?C.orange:C.red}
function tierName(c){return c>=1.2?'Đủ tiền':c>=1?'Sát ngưỡng':c>=0.7?'Hụt vừa':'Hụt nặng'}
function niceTicks(max,n=5){const s=Math.pow(10,Math.floor(Math.log10(max/n)));const m=[1,2,2.5,5,10].find(k=>k*s*n>=max);const st=m*s;const r=[];for(let v=0;v<=max+1e-9;v+=st)r.push(+v.toFixed(6));return r}

/* ---------- MODEL ---------- */
const P={s:45,dr:3,roll:60,col:30,fire:0,hc:30};
const R0=9; // lãi vay bình quân giả định %
function model(t,p){
 const b=last(t),T=D.firms[t].ttm,s=p.s/100;
 const sga=(T.sell||0)+(T.adm||0);
 const liquid=b.liquid, recv=b.short_term_receivables*p.col/100*(1-s);
 const core=T.gp*(1-s)-sga;
 const fire=b.inventory*p.fire/100*(1-p.hc/100);
 const debt=b.short_term_liabilities*(1-p.roll/100);
 const interest=T.fin*(1+p.dr/R0);
 const src=liquid+recv+core+fire, need=debt+interest;
 const gap=src-need, cov=src/need;
 // gap(s) linear: A - s*B
 const B=b.short_term_receivables*p.col/100+T.gp;
 const A=liquid+b.short_term_receivables*p.col/100+T.gp-sga+fire-need;
 const sMax=A<0?0:Math.min(100,A/B*100);
 // rollover needed: src - STL*(1-r) - interest =0
 const rNeed=Math.max(0,Math.min(100,(1-(src-interest)/b.short_term_liabilities)*100));
 return {t,liquid,recv,core,fire,debt,interest,src,need,gap,cov,sMax,A,rNeed,b,T,sga};
}

/* ---------- CLASSIFY ---------- */
const NOR={s:0,dr:0,roll:80,col:50,fire:0,hc:30};
const ROLL_MAX=80,FIRE_MAX=10;
const G={A:{n:'Vững',c:C.green},B:{n:'Theo dõi',c:C.ochre},C:{n:'Cần hỗ trợ thanh khoản',c:C.orange},D:{n:'Stress cao',c:C.red}};
function burden(m,p){p=p||P;if(m.gap>=0)return{S:0,inv:0,bank:0,rest:0};const S=-m.gap;
 const inv=Math.min(S,m.b.inventory*Math.max(0,FIRE_MAX-p.fire)/100*(1-p.hc/100));
 const bank=Math.min(S-inv,m.b.short_term_liabilities*Math.max(0,ROLL_MAX-p.roll)/100);
 return{S,inv,bank,rest:Math.max(0,S-inv-bank)}}
function classify(m,p){const de=m.b.de,why=[];const bu=burden(m,p);
 if(m.cov>=1){if(m.cov<1.2)why.push('phủ < 1,2×');if(m.sMax<45)why.push('s* < 45%');if(de>1.5)why.push('D/E > 1,5');return{g:why.length?'B':'A',why:why.length?why.join(' · '):'đạt cả 4 tiêu chí',bu}}
 why.push('phủ < 1,0×');if(bu.rest>0)why.push('công cụ thông thường không lấp đủ');if(de>2)why.push('D/E > 2');
 return{g:(bu.rest>0||de>2)?'D':'C',why:why.join(' · '),bu}}
function full(t,p){p=p||P;const m=model(t,p);const c=classify(m,p);return{...m,...c}}
const gcol=t=>G[full(t).g].c;

/* ---------- HERO ---------- */
function hero(){
 const r=F.map(t=>model(t,P));
 const neg=r.filter(x=>x.gap<0);
 const tot=neg.reduce((a,x)=>a+x.gap,0);
 const now=F.filter(t=>last(t).gap<0).length;
 document.getElementById('heroLead').innerHTML=`Chín chủ đầu tư nhà ở niêm yết, ${fmt(F.reduce((a,t)=>a+last(t).total_assets,0)/1000)} nghìn tỷ đồng tài sản. Ngay hôm nay <b>${now}/9</b> doanh nghiệp có tiền ít hơn nợ ngắn hạn. Nếu doanh số rơi ${P.s}% và lãi suất tăng ${P.dr} điểm % như 2022–2023, với ngân hàng chỉ gia hạn ${P.roll}% nợ đến hạn, <b>${neg.length} doanh nghiệp hụt tổng cộng ${fmt(-tot)} tỷ đồng</b>. Phân loại: ${['A','B','C','D'].map(k=>`<b>${r.filter(x=>classify(x).g==k).length}</b> ${G[k].n.toLowerCase()}`).join(' · ')}.`;
 const box=document.getElementById('heroTiles');box.innerHTML='';
 r.map(x=>({...x,...classify(x)})).sort((a,b)=>a.g.localeCompare(b.g)||b.cov-a.cov).forEach(x=>{const d=document.createElement('div');d.className='tile';d.style.background=G[x.g].c;
  d.innerHTML=`<div class="t">${x.t}</div><div class="v">${x.g} · ${G[x.g].n} · ${fx(x.cov)}</div>`;
  d.onmousemove=e=>showTip(e,`<b>${NAME[x.t]}</b><br>Nguồn tiền 12T: ${fmt(x.src)} tỷ<br>Nhu cầu trả nợ: ${fmt(x.need)} tỷ<br>Chênh lệch: <b>${fmt(x.gap)}</b> tỷ`);d.onmouseleave=hideTip;box.appendChild(d)});
}

/* ---------- 1 ---------- */
function p1(){
 const rows=F.map(t=>({t,...last(t)})).sort((a,b)=>a.cov-b.cov);
 const W=640,rh=38,H=rows.length*rh+40,L=130,max=1.4;const g=svg('c1',W,H);
 const x=v=>L+Math.min(v,max)/max*(W-L-60);
 [0,0.25,0.5,0.75,1,1.25].forEach(v=>{el('line',{x1:x(v),x2:x(v),y1:10,y2:H-24,stroke:v==1?C.ink:C.line,'stroke-width':v==1?1.5:1,'stroke-dasharray':v==1?'':'2 3'},g);el('text',{x:x(v),y:H-6,'text-anchor':'middle','font-size':12,fill:C.mute},g,fmt(v,2)+'×')});
 rows.forEach((r,i)=>{const y=14+i*rh;
  el('text',{x:0,y:y+16,'font-size':14,'font-weight':600,fill:C.ink},g,r.t);
  el('text',{x:44,y:y+16,'font-size':12,fill:C.mute},g,NAME[r.t].slice(0,13));
  const bar=el('rect',{x:L,y:y+3,width:x(r.cov)-L,height:20,fill:gcol(r.t),rx:1},g);
  el('text',{x:x(r.cov)+6,y:y+18,'font-size':13,'font-family':'JetBrains Mono',fill:C.ink},g,fx(r.cov));
  hover(bar,()=>`<b>${NAME[r.t]}</b><br>Tiền + ĐT ngắn hạn: ${fmt(r.liquid)} tỷ<br>Nợ ngắn hạn: ${fmt(r.short_term_liabilities)} tỷ<br>Khoảng hụt: <b>${fmt(r.gap)}</b> tỷ`)});
 let h='<table><tr><th>Mã</th><th class="r">Tài sản TK</th><th class="r">Nợ NH</th><th class="r">Khoảng hụt</th><th class="r">% tổng TS</th></tr>';
 rows.slice().sort((a,b)=>a.gap-b.gap).forEach(r=>h+=`<tr><td><b>${r.t}</b></td><td class="r num">${fmt(r.liquid)}</td><td class="r num">${fmt(r.short_term_liabilities)}</td><td class="r num" style="color:${r.gap<0?C.red:C.green}">${fmt(r.gap)}</td><td class="r num">${fmt(r.gap/r.total_assets*100,1)}%</td></tr>`);
 document.getElementById('t1').innerHTML=h+'</table>';
}

/* ---------- 2 ---------- */
function p2(){
 const per=['2025Q4','2026Q1','2026Q2','2026Q3'];const W=1080,H=380,L=50,R=150,T=20,B=40;const g=svg('c2',W,H);
 const max=1.4;const x=i=>L+i*(W-L-R)/3, y=v=>T+(1-Math.min(v,max)/max)*(H-T-B);
 [0,0.2,0.4,0.6,0.8,1,1.2,1.4].forEach(v=>{el('line',{x1:L,x2:W-R,y1:y(v),y2:y(v),stroke:v==1?C.ink:C.line,'stroke-width':v==1?1.5:1,'stroke-dasharray':v==1?'':'2 3'},g);el('text',{x:L-8,y:y(v)+4,'text-anchor':'end','font-size':12,fill:C.mute},g,fmt(v,1)+'×')});
 el('text',{x:W-R+4,y:y(1)-6,'font-size':12,fill:C.ink},g,'Ngưỡng đủ tiền 1,0×');
 per.forEach((p,i)=>el('text',{x:x(i),y:H-12,'text-anchor':'middle','font-size':13,fill:C.ink2||C.ink},g,p));
 const lab=[];
 F.forEach(t=>{const v=D.firms[t].bs.map(r=>r.cov);const c=gcol(t);
  const path=el('path',{d:v.map((c,i)=>(i?'L':'M')+x(i)+','+y(c)).join(''),fill:'none',stroke:c,'stroke-width':2.5,opacity:.9},g);
  v.forEach((c2,i)=>{const d=el('circle',{cx:x(i),cy:y(c2),r:4.5,fill:c,stroke:'#f4f5f1','stroke-width':1.5},g);hover(d,()=>`<b>${t}</b> ${per[i]}<br>Hệ số phủ: ${fx(c2)}<br>Tiền+ĐT NH: ${fmt(D.firms[t].bs[i].liquid)} tỷ<br>Nợ NH: ${fmt(D.firms[t].bs[i].short_term_liabilities)} tỷ`)});
  lab.push({t,y:y(v[3]),c,v:v[3]});});
 lab.sort((a,b)=>a.y-b.y);for(let i=1;i<lab.length;i++)if(lab[i].y-lab[i-1].y<15)lab[i].y=lab[i-1].y+15;
 lab.forEach(l=>el('text',{x:x(3)+12,y:l.y+4,'font-size':13,'font-weight':600,fill:l.c},g,`${l.t} ${fx(l.v)}`));
}

/* ---------- 3 ---------- */
function p3(){
 const rows=F.map(t=>last(t)).map((b,i)=>({t:F[i],b}));rows.sort((a,b)=>(b.b.inventory/b.b.current_assets)-(a.b.inventory/a.b.current_assets));
 const W=1080,rh=40,L=70,H=rows.length*rh+40,g=svg('c3',W,H),w=W-L-40;
 [0,25,50,75,100,125].forEach(v=>{const xx=L+v/125*w;el('line',{x1:xx,x2:xx,y1:6,y2:H-24,stroke:C.line,'stroke-dasharray':'2 3'},g);el('text',{x:xx,y:H-6,'text-anchor':'middle','font-size':12,fill:C.mute},g,v+'%')});
 rows.forEach((r,i)=>{const b=r.b,y=10+i*rh,ca=b.current_assets;
  const parts=[['Tiền + ĐT ngắn hạn',b.liquid,C.teal],['Phải thu ngắn hạn',b.short_term_receivables,'#8fb3ae'],['Hàng tồn kho',b.inventory,C.ochre]];
  const other=Math.max(0,ca-parts.reduce((a,p)=>a+p[1],0));parts.push(['TS ngắn hạn khác',other,'#c9c2b0']);
  el('text',{x:0,y:y+18,'font-size':14,'font-weight':600,fill:C.ink},g,r.t);
  let x0=L;parts.forEach(p=>{const ww=p[1]/ca/1.25*w;const rc=el('rect',{x:x0,y:y+2,width:Math.max(0,ww),height:24,fill:p[2]},g);
   if(ww>38)el('text',{x:x0+ww/2,y:y+18,'text-anchor':'middle','font-size':11,fill:'#fff','pointer-events':'none'},g,fmt(p[1]/ca*100,0)+'%');
   hover(rc,()=>`<b>${r.t}</b> · ${p[0]}<br>${fmt(p[1])} tỷ = ${fmt(p[1]/ca*100,1)}% TS ngắn hạn`);x0+=ww;});
  const sx=L+Math.min(b.short_term_liabilities/ca,1.25)/1.25*w;
  const m=el('rect',{x:sx-1.5,y:y-2,width:3,height:32,fill:C.ink},g);hover(m,()=>`<b>${r.t}</b> · Nợ ngắn hạn<br>${fmt(b.short_term_liabilities)} tỷ = ${fmt(b.short_term_liabilities/ca*100,1)}% TS ngắn hạn`);
 });
}

/* ---------- 4 ---------- */
function p4(){
 const W=620,H=440,L=56,R=20,T=20,B=48,g=svg('c4',W,H);
 const xm=3.6,ym=1.3;const x=v=>L+v/xm*(W-L-R),y=v=>T+(1-v/ym)*(H-T-B);
 el('rect',{x:x(1.5),y:y(1),width:x(xm)-x(1.5),height:y(0)-y(1),fill:'#a8322d',opacity:.07},g);
