    dev.push(`<b>3–6 tháng:</b> đẩy thu tiền ở dự án đang bàn giao, chiết khấu cho khách thanh toán sớm; bán sỉ/bán chọn lọc ~${fmt(Math.min(fireNeed,b.inventory*0.1))} tỷ tồn kho${firePct>10?` (khoảng hụt <b>${fmt(-m.gap)} tỷ</b> cần tới ${fmt(firePct,0)}% tồn kho — bán lẻ không đủ, nên chuyển nhượng một phần dự án đã đủ pháp lý hoặc tìm đối tác góp vốn dự án)`:''}.`);
    dev.push(`<b>6–12 tháng (dự phòng):</b> ${m.bu.rest>0?`phần còn thiếu ~<b>${fmt(m.bu.rest)} tỷ</b> cần `:''}vay cổ đông lớn/công ty mẹ hoặc phát hành riêng lẻ cho nhà đầu tư chiến lược.`);
    if(b.de>2)dev.push(`D/E ${fmt(b.de,2)} lần: không vay mới để trả nợ cũ; nguồn vốn mới nên là vốn chủ hoặc vốn đối tác dự án.`);
   }else{
    dev.push(`Khoảng hụt <b>${fmt(-m.gap)} tỷ</b>: tự lấp ${fmt(m.bu.inv)} tỷ bằng bán ${fmt(m.bu.inv/(1-P.hc/100)/b.inventory*100,1)}% tồn kho; cần ngân hàng gia hạn tối thiểu <b>${fmt(m.rNeed,0)}%</b> nợ ngắn hạn (hiện ${P.roll}%).`);
    if(m.bu.rest>0)dev.push(`Còn <b>${fmt(m.bu.rest)} tỷ</b> cần vay cổ đông lớn hoặc đối tác góp vốn dự án.`);
    if(b.de>2)dev.push(`D/E ${fmt(b.de,2)} lần: không vay thêm.`);
   }
  }else{
   dev.push(`Dư <b>${fmt(m.gap)} tỷ</b> ở kịch bản này; doanh số giảm quá <b>${m.sMax>=100?'100':fmt(m.sMax,0)}%</b> mới hụt.`);
  }
  if(cashChg<-40)dev.push(`Tiền & ĐT ngắn hạn đã giảm ${fmt(-cashChg,0)}% từ 2025Q4 — cần giải trình dòng tiền ra.`);
  const d=document.createElement('div');d.className='rec';d.style.borderLeftColor=G[m.g].c;
  d.innerHTML=`<h4>${m.t} <span style="font-size:14px;font-family:Be Vietnam Pro;color:${C.mute}">${NAME[m.t]}</span> <span class="badge" style="background:${G[m.g].c};float:right">${m.g} · ${G[m.g].n}</span></h4><div style="font-size:12.5px;color:${C.mute}">${fx(m.cov)} · ${m.why}</div><div class="who">Chủ đầu tư nên làm</div><ul>${dev.map(x=>'<li>'+x+'</li>').join('')}</ul>`;box.appendChild(d)});
}
function p7(){
 const r=F.map(t=>full(t)).sort((a,b)=>a.g.localeCompare(b.g)||b.cov-a.cov);
 const ok=(v)=>`<span style="color:${v?C.green:C.red};font-weight:700">${v?'✓':'✕'}</span>`;
 let h='<table><tr><th>Mã</th><th class="r">① Hệ số phủ</th><th class="r">② s*</th><th class="r">③ Lấp được?</th><th class="r">④ D/E</th><th>Nhóm</th><th>Lý do</th></tr>';
 r.forEach(m=>h+=`<tr><td><b>${m.t}</b></td><td class="r num">${fx(m.cov)} ${ok(m.cov>=1.2)}</td><td class="r num">${m.A<0?'0%':m.sMax>=100?'>100%':fmt(m.sMax,0)+'%'} ${ok(m.sMax>=45)}</td><td class="r num">${m.gap>=0?'không hụt':(m.bu.rest>0?fmt(m.bu.rest)+' tỷ thiếu ':'đủ ')+ok(m.bu.rest==0)}</td><td class="r num">${fmt(m.b.de,2)} ${ok(m.b.de<=1.5)}</td><td><span class="badge" style="background:${G[m.g].c}">${m.g} · ${G[m.g].n}</span></td><td style="font-size:13px;color:${C.ink2||C.ink}">${m.why}</td></tr>`);
 document.getElementById('t7').innerHTML=h+'</table>';
}
function p8(){
 const base=F.map(t=>full(t));
 const pols=[['Siết đồng loạt 40%',()=>40],[`Giữ đồng loạt ${P.roll}%`,()=>P.roll],['Nới đồng loạt 80%',()=>80],['Phân hóa theo nhóm',m=>m.g=='A'?Math.min(P.roll,Math.ceil(m.rNeed)+10):m.g=='C'?Math.min(80,Math.max(P.roll,Math.ceil(m.rNeed))):P.roll]];
 let h='<table><tr><th>Chính sách</th><th class="r">DN hụt tiền</th><th class="r">Tổng khoảng hụt, tỷ</th><th class="r">Gia hạn cho nhóm A, tỷ</th><th class="r">Gia hạn cho nhóm D, tỷ</th></tr>';
 pols.forEach(([n,f],i)=>{let cnt=0,sh=0,ga=0,gd=0;base.forEach(m0=>{const roll=f(m0);const m=model(m0.t,{...P,roll});if(m.gap<0){cnt++;sh+=m.gap}const v=m0.b.short_term_liabilities*roll/100;if(m0.g=='A')ga+=v;if(m0.g=='D')gd+=v});
  h+=`<tr style="${i==3?'background:#e6efe8;font-weight:600':''}"><td>${n}</td><td class="r num">${cnt}/9</td><td class="r num" style="color:${sh<0?C.red:C.green}">${fmt(sh)}</td><td class="r num">${fmt(ga)}</td><td class="r num">${fmt(gd)}</td></tr>`});
 document.getElementById('t8').innerHTML=h+'</table>';
 // burden chart
 const rows=base.filter(m=>m.gap<0&&m.t!='VHM').sort((a,b)=>b.bu.S-a.bu.S);const vh=base.find(m=>m.t=='VHM'&&m.gap<0);
 const W=560,rh=38,L=50,H=Math.max(1,rows.length)*rh+40,g=svg('c8',W,H);
 if(!rows.length){el('text',{x:0,y:20,'font-size':14,fill:C.ink},g,'Không có doanh nghiệp hụt tiền (ngoài VHM) ở kịch bản này.');}
 const mx=Math.max(1,...rows.map(m=>m.bu.S));const x=v=>v/mx*(W-L-90);
 rows.forEach((m,i)=>{const y=8+i*rh;el('text',{x:0,y:y+17,'font-size':14,'font-weight':600,fill:C.ink},g,m.t);let x0=L;
  [['inv',C.teal,'Doanh nghiệp tự xoay: bán tồn kho'],['bank',C.ochre,'Ngân hàng gia hạn thêm'],['rest',C.red,'Phần còn thiếu: đối tác dự án / cổ đông']].forEach(([k,c,n])=>{const w=x(m.bu[k]);if(w<=0)return;const rc=el('rect',{x:x0,y:y+3,width:w,height:22,fill:c},g);hover(rc,()=>`<b>${m.t}</b> · ${n}<br>${fmt(m.bu[k])} tỷ (${fmt(m.bu[k]/m.bu.S*100,0)}% khoảng hụt)`);x0+=w});
  el('text',{x:x0+6,y:y+19,'font-size':12,'font-family':'JetBrains Mono',fill:C.ink},g,fmt(m.bu.S)+' tỷ')});
 el('text',{x:0,y:H-8,'font-size':12,fill:C.mute},g,vh?`VHM (ngoài thang): hụt ${fmt(vh.bu.S)} tỷ — tự xoay ${fmt(vh.bu.inv)}, ngân hàng ${fmt(vh.bu.bank)}, còn thiếu ${fmt(vh.bu.rest)}.`:'');
 // group cards
 const gb=document.getElementById('g8');gb.innerHTML='';const tot=base.reduce((a,m)=>a+m.b.short_term_liabilities,0);
 ['D','C','B','A'].forEach(k=>{const mem=base.filter(m=>m.g==k);const ex=mem.reduce((a,m)=>a+m.b.short_term_liabilities,0);const d=document.createElement('div');d.className='gcard';d.style.borderTopColor=G[k].c;
  d.innerHTML=`<h4>${k} · ${G[k].n}</h4><div class="mem">${mem.length?mem.map(m=>m.t).join(', '):'— chưa có DN —'} · nợ NH ${fmt(ex)} tỷ (${fmt(ex/tot*100,0)}%)</div><dl><dt>Ngân hàng</dt>${PLAY[k].bank.map(x=>'<dd>• '+x+'</dd>').join('')}</dl>`;gb.appendChild(d)});
}
function p10(){
 const chans=[['s','Doanh số giảm'],['roll','Gia hạn giảm'],['col','Thu hồi phải thu giảm'],['dr','Lãi suất tăng'],['fire','Bán tháo tồn kho']];
 const med=a=>{a=a.slice().sort((x,y)=>x-y);const n=a.length;return n%2?a[(n-1)/2]:(a[n/2-1]+a[n/2])/2};
 const res=chans.map(([k,n])=>{const d=F.map(t=>model(t,{...NOR,[k]:P[k]}).cov-model(t,NOR).cov);const gx=F.filter(t=>t!='VHM').reduce((a,t)=>a+model(t,{...NOR,[k]:P[k]}).gap-model(t,NOR).gap,0);return{k,n,v:med(d),gx}}).filter(r=>Math.abs(r.v)>1e-6||r.k!='fire').sort((a,b)=>a.v-b.v);
 const W=560,rh=44,L=170,H=res.length*rh+40,g=svg('c10',W,H);const mn=Math.min(-0.1,...res.map(r=>r.v)),mxv=Math.max(0.1,...res.map(r=>r.v));
 const x=v=>L+(v-mn)/(mxv-mn)*(W-L-70);el('line',{x1:x(0),x2:x(0),y1:0,y2:H-24,stroke:C.ink},g);
 res.forEach((r,i)=>{const y=6+i*rh;el('text',{x:0,y:y+18,'font-size':14,fill:C.ink},g,r.n);const a=x(Math.min(0,r.v)),b=x(Math.max(0,r.v));
  const rc=el('rect',{x:a,y:y+4,width:Math.max(1,b-a),height:22,fill:r.k=='dr'?C.ochre:r.v<0?C.red:C.teal},g);
  el('text',{x:r.v<0?a-6:b+6,y:y+20,'text-anchor':r.v<0?'end':'start','font-size':12,'font-family':'JetBrains Mono',fill:C.ink},g,(r.v>0?'+':'')+fmt(r.v,2)+'×');
  hover(rc,()=>`<b>${r.n}</b><br>Hệ số phủ trung vị: ${(r.v>0?'+':'')+fmt(r.v,2)}×<br>Chênh lệch 8 DN (trừ VHM): ${fmt(r.gx)} tỷ`)});
 el('text',{x:L,y:H-6,'font-size':11,fill:C.mute},g,'Từ kịch bản “Bình thường”, đổi từng tham số một sang kịch bản đang chọn');
 const base=F.map(t=>full(t));const sh=base.filter(m=>m.gap<0);const tot=base.reduce((a,m)=>a+m.b.short_term_liabilities,0);
 const dEx=base.filter(m=>m.g=='D').reduce((a,m)=>a+m.b.short_term_liabilities,0);
 const bankExtra=sh.reduce((a,m)=>a+m.bu.bank,0),eq=sh.reduce((a,m)=>a+m.bu.rest,0);
 const rate=res.find(r=>r.k=='dr'),roll=res.find(r=>r.k=='roll'),sale=res.find(r=>r.k=='s');
 document.getElementById('k10').innerHTML=[[`${sh.length}/9`,'doanh nghiệp hụt tiền trong 12 tháng'],[fmt(dEx/tot*100,0)+'%','nợ ngắn hạn của mẫu nằm ở nhóm D'],[fmt(bankExtra)+' tỷ','ngân hàng cần gia hạn thêm (đến 80%) để lấp khoảng hụt'],[fmt(eq)+' tỷ','còn thiếu sau bán tồn kho và gia hạn — cần đối tác/cổ đông trong 6–12 tháng']].map(([v,l])=>`<div class="kpi"><div class="v num">${v}</div><div class="l">${l}</div></div>`).join('');
 const pol=[
  `<b>NHNN: cơ cấu nợ có chọn lọc, không giãn nợ đại trà.</b> Kênh gia hạn làm hệ số phủ trung vị giảm ${fmt(Math.abs(roll?roll.v:0),2)}×, mạnh hơn lãi suất ${rate&&rate.v?fmt(Math.abs(roll.v/rate.v),0):'–'} lần. Cho phép giữ nhóm nợ khi cơ cấu kỳ hạn, nhưng ưu tiên doanh nghiệp nhóm C có phương án bán hàng khả thi; với nhóm D, cơ cấu kỳ hạn gắn với kế hoạch dòng tiền và cam kết hỗ trợ của cổ đông lớn/công ty mẹ.`,
  `<b>Chính phủ: khơi lại doanh số bằng tháo gỡ pháp lý, không bằng tiền.</b> Doanh số giảm là kênh lớn thứ hai (−${fmt(Math.abs(sale?sale.v:0),2)}× trung vị). Ưu tiên cấp phép, bàn giao các dự án đã bán trước để giải phóng tiền khách hàng đang treo, và tín dụng cho người mua nhà ở thực.`,
  `<b>Lãi suất: không phải đòn bẩy chính.</b> Lãi suất tăng ${fmt(P.dr,1)} điểm % chỉ làm hệ số phủ trung vị giảm ${fmt(Math.abs(rate?rate.v:0),2)}×. Hạ lãi suất đại trà để cứu doanh nghiệp BĐS hiệu quả thấp và đánh đổi áp lực tỷ giá khi Fed đang tăng lãi suất.`,
  `<b>Trái phiếu: cơ chế đàm phán trái chủ.</b> Sửa điều khoản trái phiếu cần đa số trái chủ đồng ý theo quy định hiện hành; cần đầu mối trung gian (đại lý quản lý tài sản bảo đảm, tổ chức xếp hạng) để giãn kỳ hạn hoặc thanh toán bằng tài sản cho nhóm D, tránh để chậm trả lan rộng.`,
  `<b>Minh bạch dữ liệu: bắt buộc công bố lịch đáo hạn nợ và tách tiền người mua trả trước.</b> Thiếu hai chỉ tiêu này, ngân hàng và nhà quản lý không phân biệt được VHM (nợ chủ yếu là tiền khách trả trước) với một doanh nghiệp thiếu tiền thật. NHNN nên stress test khối khách hàng BĐS định kỳ hàng quý theo bộ tiêu chí ở phần 7.`];
 document.getElementById('pol10').innerHTML=pol.map(x=>'<li>'+x+'</li>').join('');
}
